    CREATE TABLE #ExampleCommitExpected([FinalCommitEventOrdinal] bigint NOT NULL, [LogId] int NOT NULL, [ExecutionId] uniqueidentifier NOT NULL, [EventName] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [SourceId] uniqueidentifier NULL, [SourceName] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [EventTime] datetime NULL, [DataCode] int NULL, [ParserId] varchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [ParseStatus] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [ObservationKind] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [ComponentName] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [ContextStatus] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [ContextStartLogId] int NULL, [ContextEndLogId] int NULL, [InputIsTruncated] bit NOT NULL, [EvidenceLevel] varchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [EvidenceSource] nvarchar(160) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [MessageText] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    SELECT TOP(0) * INTO #ExampleCommitActual FROM #ExampleCommitExpected;
    DECLARE @Case int=1,@Label varchar(40),@Cap int,@Input nvarchar(max),@Expected nvarchar(max),@C int,@P int,@A int,@Limited bit;
    WHILE @Case<=28
    BEGIN
        SELECT @Label=Label,@Cap=Cap,@Input=InputJson,@Expected=ExpectedJson,@C=Candidates,@P=Parsed,@A=Assigned,@Limited=Limited FROM #ExampleCommitCases WHERE CaseId=@Case;
        DELETE dbo.ExampleFinalCommitLogSource;
        INSERT dbo.ExampleFinalCommitLogSource SELECT id,event,source,sourceid,executionid,starttime,endtime,datacode,message FROM OPENJSON(@Input) WITH(id int,event nvarchar(128),source nvarchar(128),sourceid uniqueidentifier,executionid uniqueidentifier,starttime datetime,endtime datetime,datacode int,message nvarchar(max));
        EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleFinalCommitLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeFinalCommitAnalysis=1,@MaxZeilen=@Cap,@ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@ErrorNumberOut=@Error OUTPUT,@ErrorMessageOut=@Message OUTPUT;
        IF @Error IS NOT NULL OR @Message IS NOT NULL THROW 57004,N'FC_UNEXPECTED_NATIVE_ERROR',1;
        DELETE #ExampleCommitExpected;DELETE #ExampleCommitActual;
        INSERT #ExampleCommitExpected SELECT [FinalCommitEventOrdinal], [LogId], [ExecutionId], [EventName], [SourceId], [SourceName], [EventTime], [DataCode], [ParserId], [ParseStatus], [ObservationKind], [ComponentName], [ContextStatus], [ContextStartLogId], [ContextEndLogId], [InputIsTruncated], [EvidenceLevel], [EvidenceSource], [MessageText] FROM OPENJSON(@Expected) WITH([FinalCommitEventOrdinal] bigint '$.FinalCommitEventOrdinal', [LogId] int '$.LogId', [ExecutionId] uniqueidentifier '$.ExecutionId', [EventName] nvarchar(128) '$.EventName', [SourceId] uniqueidentifier '$.SourceId', [SourceName] nvarchar(4000) '$.SourceName', [EventTime] datetime '$.EventTime', [DataCode] int '$.DataCode', [ParserId] varchar(32) '$.ParserId', [ParseStatus] varchar(40) '$.ParseStatus', [ObservationKind] varchar(40) '$.ObservationKind', [ComponentName] nvarchar(4000) '$.ComponentName', [ContextStatus] varchar(40) '$.ContextStatus', [ContextStartLogId] int '$.ContextStartLogId', [ContextEndLogId] int '$.ContextEndLogId', [InputIsTruncated] bit '$.InputIsTruncated', [EvidenceLevel] varchar(32) '$.EvidenceLevel', [EvidenceSource] nvarchar(160) '$.EvidenceSource', [MessageText] nvarchar(max) '$.MessageText');
        INSERT #ExampleCommitActual SELECT [FinalCommitEventOrdinal], [LogId], [ExecutionId], [EventName], [SourceId], [SourceName], [EventTime], [DataCode], [ParserId], [ParseStatus], [ObservationKind], [ComponentName], [ContextStatus], [ContextStartLogId], [ContextEndLogId], [InputIsTruncated], [EvidenceLevel], [EvidenceSource], [MessageText] FROM OPENJSON(@J,'$.finalCommitEvents') WITH([FinalCommitEventOrdinal] bigint '$.FinalCommitEventOrdinal', [LogId] int '$.LogId', [ExecutionId] uniqueidentifier '$.ExecutionId', [EventName] nvarchar(128) '$.EventName', [SourceId] uniqueidentifier '$.SourceId', [SourceName] nvarchar(4000) '$.SourceName', [EventTime] datetime '$.EventTime', [DataCode] int '$.DataCode', [ParserId] varchar(32) '$.ParserId', [ParseStatus] varchar(40) '$.ParseStatus', [ObservationKind] varchar(40) '$.ObservationKind', [ComponentName] nvarchar(4000) '$.ComponentName', [ContextStatus] varchar(40) '$.ContextStatus', [ContextStartLogId] int '$.ContextStartLogId', [ContextEndLogId] int '$.ContextEndLogId', [InputIsTruncated] bit '$.InputIsTruncated', [EvidenceLevel] varchar(32) '$.EvidenceLevel', [EvidenceSource] nvarchar(160) '$.EvidenceSource', [MessageText] nvarchar(max) '$.MessageText');
        IF EXISTS(SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitExpected EXCEPT SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitActual) OR EXISTS(SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitActual EXCEPT SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitExpected)
            OR (SELECT COUNT(*) FROM #ExampleCommitActual)<>@C OR EXISTS(SELECT 1 FROM OPENJSON(@J,'$.finalCommitEvents') r WHERE (SELECT COUNT(*) FROM OPENJSON(r.value))<>19)
        BEGIN SELECT @Case AS FailedCase,@Label AS FailedLabel,@J AS FailedJson;THROW 57005,N'FC_INDEPENDENT_ALL19',1;END;
        IF NOT EXISTS(SELECT 1 FROM OPENJSON(@J,'$.sourceStatus') WHERE JSON_VALUE(value,'$.SourceOrdinal')=N'11' AND JSON_VALUE(value,'$.SourceName')=N'finalCommitAnalysis' AND JSON_VALUE(value,'$.StatusCode')=CASE WHEN @Limited=1 THEN 'AVAILABLE_LIMITED' WHEN @C=0 THEN 'AVAILABLE_EMPTY' ELSE 'AVAILABLE' END AND JSON_VALUE(value,'$.Detail')=N'Candidates='+CONVERT(nvarchar(20),@C)+N';Parsed='+CONVERT(nvarchar(20),@P)+N';ContextAssigned='+CONVERT(nvarchar(20),@A)) THROW 57006,N'FC_SPARSE_COUNTERS',1;
        SET @Case+=1;
    END;
    CREATE TABLE #ExampleCommitExport(Seed int NULL);
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleFinalCommitLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeFinalCommitAnalysis=1,@ResultSetArt='TABLE',@ResultTablesJson=N'{"finalCommitEvents":"#ExampleCommitExport"}',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    DECLARE @ExportMatches bit=0;
    EXEC sys.sp_executesql N'SET @Ok=CASE WHEN NOT EXISTS(SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitExport EXCEPT SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitExpected) AND NOT EXISTS(SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitExpected EXCEPT SELECT [FinalCommitEventOrdinal] AS [FinalCommitEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[ComponentName]) AS [ComponentName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleCommitExport) AND (SELECT COUNT(*) FROM #ExampleCommitExport)=(SELECT COUNT(*) FROM #ExampleCommitExpected) THEN 1 ELSE 0 END;',N'@Ok bit OUTPUT',@Ok=@ExportMatches OUTPUT;
    IF @ExportMatches<>1 THROW 57007,N'FC_TABLE_VALUES',1;
    CREATE TABLE #ExampleCommitSchema(Ordinal int,Name sysname,TypeName sysname,MaxLength smallint,Prec tinyint,Scale tinyint,Nullable bit,CollationName sysname NULL);
    INSERT #ExampleCommitSchema VALUES
(1,N'FinalCommitEventOrdinal',N'bigint',8,19,0,0,NULL),
(2,N'LogId',N'int',4,10,0,0,NULL),
(3,N'ExecutionId',N'uniqueidentifier',16,0,0,0,NULL),
(4,N'EventName',N'nvarchar',256,0,0,1,N'SQL_Latin1_General_CP1_CS_AS'),
(5,N'SourceId',N'uniqueidentifier',16,0,0,1,NULL),
(6,N'SourceName',N'nvarchar',8000,0,0,1,N'SQL_Latin1_General_CP1_CS_AS'),
(7,N'EventTime',N'datetime',8,23,3,1,NULL),
(8,N'DataCode',N'int',4,10,0,1,NULL),
(9,N'ParserId',N'varchar',32,0,0,1,N'SQL_Latin1_General_CP1_CS_AS'),
(10,N'ParseStatus',N'varchar',40,0,0,0,N'SQL_Latin1_General_CP1_CS_AS'),
(11,N'ObservationKind',N'varchar',40,0,0,1,N'SQL_Latin1_General_CP1_CS_AS'),
(12,N'ComponentName',N'nvarchar',8000,0,0,1,N'SQL_Latin1_General_CP1_CS_AS'),
(13,N'ContextStatus',N'varchar',40,0,0,0,N'SQL_Latin1_General_CP1_CS_AS'),
(14,N'ContextStartLogId',N'int',4,10,0,1,NULL),
(15,N'ContextEndLogId',N'int',4,10,0,1,NULL),
(16,N'InputIsTruncated',N'bit',1,1,0,0,NULL),
(17,N'EvidenceLevel',N'varchar',32,0,0,0,N'SQL_Latin1_General_CP1_CS_AS'),
(18,N'EvidenceSource',N'nvarchar',320,0,0,0,N'SQL_Latin1_General_CP1_CS_AS'),
(19,N'MessageText',N'nvarchar',-1,0,0,1,N'SQL_Latin1_General_CP1_CS_AS');
    IF EXISTS(SELECT * FROM #ExampleCommitSchema EXCEPT SELECT CONVERT(int,ROW_NUMBER() OVER(ORDER BY c.column_id)),c.name,t.name,c.max_length,c.precision,c.scale,c.is_nullable,c.collation_name FROM tempdb.sys.columns c JOIN tempdb.sys.types t ON t.user_type_id=c.user_type_id WHERE c.object_id=OBJECT_ID(N'tempdb..#ExampleCommitExport')) OR (SELECT COUNT(*) FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#ExampleCommitExport'))<>19 OR EXISTS(SELECT 1 FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#ExampleCommitExport') AND (is_identity=1 OR is_computed=1)) THROW 57008,N'FC_TABLE_NATIVE_SCHEMA',1;
    DECLARE @MapCase int=1,@Map nvarchar(max),@Caught int;
    WHILE @MapCase<=6
    BEGIN
        SET @Map=CASE @MapCase WHEN 1 THEN N'{"unknownWriteSet":"#ExampleCommitExport"}' WHEN 2 THEN N'{"finalCommitEvents":"#ExampleCommitExport"}'
            WHEN 3 THEN N'{"finalCommitEvents":"#ExampleCommitExport","finalCommitEvents":"#ExampleCommitExport"}'
            WHEN 4 THEN N'{"finalCommitEvents":"#ExampleCommitExport","execution":"#ExampleCommitExport"}'
            WHEN 5 THEN N'{"finalCommitEvents":"dbo.ExampleCommitExport"}' ELSE N'broken-json' END;
        SET @Commit=CASE WHEN @MapCase=2 THEN 0 ELSE 1 END;SET @Caught=NULL;
        BEGIN TRY
            EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeFinalCommitAnalysis=@Commit,@ResultSetArt='TABLE',@ResultTablesJson=@Map,@PrintMeldungen=0;
        END TRY BEGIN CATCH SET @Caught=ERROR_NUMBER();END CATCH;
        IF ISNULL(@Caught,0)<>51011 THROW 57008,N'FC_MAPPING_REJECTION',1;
        SET @MapCase+=1;
    END;
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleFinalCommitLogSource',@ExecutionId=@Id,@HighImpactConfirmed=0,@IncludeFinalCommitAnalysis=1,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@StatusCodeOut=@Status OUTPUT;
    IF @Status<>'INVALID_PARAMETER' OR ISNULL(JSON_QUERY(@J,'$.finalCommitEvents'),N'MISSING')<>N'[]' THROW 57014,N'FC_HIGH_IMPACT_GATE',1;
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleFinalCommitLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeFinalCommitAnalysis=1,@IncludeMessages=0,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    IF ISNULL(JSON_QUERY(@J,'$.finalCommitEvents'),N'MISSING')<>N'[]' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@J,'$.sourceStatus') WHERE JSON_VALUE(value,'$.SourceName')=N'finalCommitAnalysis' AND JSON_VALUE(value,'$.Detail')=N'MESSAGES_DISABLED' AND JSON_VALUE(value,'$.ObservedRowCount') IS NULL) THROW 57009,N'FC_MESSAGES_DISABLED',1;
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleFinalCommitMissing',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeFinalCommitAnalysis=1,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    IF ISNULL(JSON_QUERY(@J,'$.finalCommitEvents'),N'MISSING')<>N'[]' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@J,'$.sourceStatus') WHERE JSON_VALUE(value,'$.SourceName')=N'finalCommitAnalysis' AND JSON_VALUE(value,'$.Detail')=N'NO_VALID_EVENT_BUFFER') THROW 57010,N'FC_MISSING_SOURCE',1;
    ALTER TABLE dbo.ExampleFinalCommitLogSource DROP COLUMN event;
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleFinalCommitLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeFinalCommitAnalysis=1,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    IF ISNULL(JSON_QUERY(@J,'$.finalCommitEvents'),N'MISSING')<>N'[]' THROW 57011,N'FC_REQUIRED_COLUMN',1;
    ALTER TABLE dbo.ExampleFinalCommitLogSource ADD event nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL;
    UPDATE dbo.ExampleFinalCommitLogSource SET event=CASE id WHEN 10 THEN N'OnPreExecute' WHEN 20 THEN N'OnInformation' ELSE N'OnPostExecute' END;
    CREATE USER ExampleFinalCommitReader WITHOUT LOGIN;
    SET @UserId=DATABASE_PRINCIPAL_ID(N'ExampleFinalCommitReader');
    GRANT EXECUTE ON SCHEMA::monitor TO ExampleFinalCommitReader;
    GRANT VIEW DEFINITION ON dbo.ExampleFinalCommitLogSource TO ExampleFinalCommitReader;
    DENY SELECT ON dbo.ExampleFinalCommitLogSource TO ExampleFinalCommitReader;
    DECLARE @DirectError int,@DirectMessage nvarchar(4000);
    BEGIN TRY
        EXECUTE AS USER='ExampleFinalCommitReader';SET @Impersonated=1;
        BEGIN TRY EXEC sys.sp_executesql N'SELECT id FROM dbo.ExampleFinalCommitLogSource;';END TRY BEGIN CATCH SELECT @DirectError=ERROR_NUMBER(),@DirectMessage=ERROR_MESSAGE();END CATCH;
        EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleFinalCommitLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeFinalCommitAnalysis=1,
            @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@ErrorNumberOut=@Error OUTPUT,@ErrorMessageOut=@Message OUTPUT;
        REVERT;SET @Impersonated=0;
    END TRY BEGIN CATCH IF @Impersonated=1 BEGIN REVERT;SET @Impersonated=0;END;THROW;END CATCH;
    IF ISNULL(@DirectError,0)<>229 OR ISNULL(@Error,0)<>229 OR @Message IS NULL OR @DirectMessage IS NULL
        OR CONVERT(varbinary(max),@Message)<>CONVERT(varbinary(max),@DirectMessage) OR ISNULL(JSON_QUERY(@J,'$.finalCommitEvents'),N'MISSING')<>N'[]' THROW 57012,N'FC_NATIVE_DENIAL',1;
    IF DATABASE_PRINCIPAL_ID(N'ExampleFinalCommitReader')<>@UserId THROW 57091,N'FC_USER_ID_CHANGED',1;
    DROP USER ExampleFinalCommitReader;SET @UserId=NULL;
    IF OBJECT_ID(N'dbo.ExampleFinalCommitLogSource')<>@TableId THROW 57092,N'FC_TABLE_ID_CHANGED',1;
    DROP TABLE dbo.ExampleFinalCommitLogSource;SET @TableId=NULL;
    IF @@OPTIONS<>@OuterOptions OR @@LOCK_TIMEOUT<>@OuterLock OR @@TRANCOUNT<>@OuterTran THROW 57013,N'FC_CALLER_CHANGED',1;
    SELECT N'PASS' AS FinalCommitSyntheticStatus,28 AS PayloadAndContextCases,128 AS FlagCases,6 AS MappingCases,5 AS SourceCases,19 AS IndependentFields;
END TRY
BEGIN CATCH
    IF @Impersonated=1 REVERT;
    IF @UserId IS NOT NULL AND DATABASE_PRINCIPAL_ID(N'ExampleFinalCommitReader')=@UserId DROP USER ExampleFinalCommitReader;
    IF @TableId IS NOT NULL AND OBJECT_ID(N'dbo.ExampleFinalCommitLogSource')=@TableId DROP TABLE dbo.ExampleFinalCommitLogSource;
    THROW;
END CATCH;
GO
